<template>
  <ion-page><ion-content :fullscreen="true"><main :class="['challenge', config.theme]">
    <header><button @click="leave">{{ t.exit }}</button><span>{{ displayName }}</span><button @click="gameLanguage=gameLanguage==='en'?'bn':'en'">{{ gameLanguage==='en'?'বাংলা':'EN' }}</button></header>
    <section v-if="stage==='intro'" class="panel intro"><p>{{ config.kicker[language] }}</p><h1>{{ displayName }}</h1><div class="hero-icon">{{ config.icon }}</div><p>{{ config.intro[language] }}</p><button class="primary" @click="start">{{ t.start }} →</button></section>
    <section v-else-if="stage==='play'" class="panel play"><div class="status"><span>{{ t.rounds }} {{ round }}/{{ rounds.length }}</span><span>{{ correct }} {{ t.matches }}</span></div>
      <template v-if="config.mode==='memory'"><p class="instruction">{{ showing ? config.show[language] : config.ask[language] }}</p><div class="sequence">{{ showing ? current.sequence.map(label).join(' · ') : selected.map(label).join(' · ') || '…' }}</div><div v-if="!showing" class="tiles"><button v-for="item in current.choices" :key="item" :disabled="locked" @click="memoryPick(item)">{{ label(item) }}</button></div></template>
      <template v-else-if="config.mode==='signal'"><p class="instruction">{{ current.target ? config.show[language] : config.ask[language] }}</p><button class="signal-orb" :class="{target:current.target}" :disabled="locked" @click="signalPick">{{ current.target?'✦':'○' }}</button><div class="two-actions"><button :disabled="locked" @click="signalPick">{{ language==='en'?'Catch signal':'সংকেত ধরো' }}</button><button :disabled="locked" @click="signalPass">{{ language==='en'?'Let it pass':'যেতে দাও' }}</button></div></template>
      <template v-else-if="config.mode==='mission'"><p class="instruction">{{ config.ask[language] }}</p><div class="build-path"><span v-for="step in selected" :key="step">{{ label(step) }}</span><i v-if="!selected.length">?</i></div><div class="tiles"><button v-for="item in current.choices" :key="item" :disabled="locked" @click="missionPick(item)">{{ label(item) }}</button></div></template>
      <template v-else-if="config.mode==='scout'"><p class="instruction">{{ language==='en'?'Find the signal in the sky':'আকাশে সংকেতটি খুঁজে নাও' }}: <b>{{ label(current.sequence[0]) }}</b></p><div class="sky-scene"><i class="cloud c1"></i><i class="cloud c2"></i><button v-for="item in current.choices" :key="item" class="sky-item" :disabled="locked" @click="scoutPick(item)">{{ label(item) }}</button></div></template>
      <template v-else-if="config.mode==='pet'"><div class="pet-scene"><span>{{ current.pet || '🐶' }}</span><i>♥</i></div><p class="story">{{ current.story?.[language] }}</p><p class="instruction">{{ config.ask[language] }}</p><div class="pet-choices"><button v-for="item in current.choices" :key="item" :disabled="locked" @click="petPick(item)">{{ label(item) }}</button></div></template>
      <template v-else-if="config.mode==='goal'"><p class="instruction">{{ config.ask[language] }}</p><div class="pitch"><span class="goal">▥</span><i class="defender left" :class="{open:current.sequence[0]==='right'}">●</i><i class="ball">⚽</i><i class="defender right" :class="{open:current.sequence[0]==='left'}">●</i></div><div class="two-actions"><button :disabled="locked" @click="goalPick('left')">{{ language==='en'?'Pass left':'বামে পাস' }} ←</button><button :disabled="locked" @click="goalPick('right')">→ {{ language==='en'?'Pass right':'ডানে পাস' }}</button></div></template>
      <template v-else><p class="instruction">{{ showing ? config.show[language] : config.ask[language] }}</p><div class="rhythm">{{ showing ? current.sequence.join(' ') : repeats.map(label).join(' ') || '· · ·' }}</div><button v-if="!showing" class="tap" :disabled="locked" @click="rhythmTap">●</button><p v-if="!showing" class="hint">{{ language==='en'?'Tap the river beat':'নদীর ছন্দে ট্যাপ করো' }}</p></template>
      <button class="finish" @click="finish">{{ t.finish }}</button>
    </section>
    <section v-else class="panel result"><p>{{ t.complete }}</p><h1>{{ correct }}/{{ answered }}</h1><span>{{ language==='en'?'A new trail will change the challenge.':'পরের পথে চ্যালেঞ্জ বদলে যাবে।' }}</span><button class="primary" @click="stage='intro'">{{ t.again }}</button><button class="link" @click="leave">{{ t.return }}</button></section>
  </main></ion-content></ion-page>
</template>

<script setup lang="ts">
import { computed, ref } from 'vue'; import { IonContent, IonPage } from '@ionic/vue'; import { useRoute, useRouter } from 'vue-router'; import { completeGame, startGame } from '@/game/core/gameApi'; import type { GameRun } from '@/game/core/types'; import { gameLanguage, gameNames, gameText } from '@/gameLanguage'; import '@/game/challenge-games.css';
type Lang='en'|'bn'; type Mode='memory'|'signal'|'mission'|'rhythm'|'goal'|'scout'|'pet'; type Round={sequence:string[];choices:string[];target?:boolean;pet?:string;story?:Record<Lang,string>}; type Config={mode:Mode;theme:string;icon:string;kicker:Record<Lang,string>;intro:Record<Lang,string>;show:Record<Lang,string>;ask:Record<Lang,string>;rounds:Round[]};
const configs:Record<string,Config>={
 'memory-market':{mode:'memory',theme:'market',icon:'◈',kicker:{en:'MEMORY MARKET',bn:'স্মৃতি বাজার'},intro:{en:'Watch a market order, then pack it in the same order.',bn:'বাজারের অর্ডার দেখো, তারপর একই ক্রমে গুছিয়ে নাও।'},show:{en:'Remember this order',bn:'এই অর্ডারটি মনে রাখো'},ask:{en:'Pack the order',bn:'অর্ডারটি গুছিয়ে নাও'},rounds:[{sequence:['mango','book'],choices:['mango','drum','book','kite']},{sequence:['lamp','kite','mango'],choices:['lamp','kite','mango','book']},{sequence:['drum','book','mango'],choices:['mango','book','drum','kite']}]},
 'signal-garden':{mode:'signal',theme:'garden',icon:'✺',kicker:{en:'SIGNAL GARDEN',bn:'সংকেত বাগান'},intro:{en:'Catch bright signals. Let quiet seeds drift by.',bn:'উজ্জ্বল সংকেত ধরো। শান্ত বীজকে যেতে দাও।'},show:{en:'A bright signal appeared',bn:'একটি উজ্জ্বল সংকেত এসেছে'},ask:{en:'A quiet seed is passing',bn:'একটি শান্ত বীজ যাচ্ছে'},rounds:[{sequence:[],choices:[],target:true},{sequence:[],choices:[],target:false},{sequence:[],choices:[],target:true},{sequence:[],choices:[],target:false},{sequence:[],choices:[],target:true}]},
 'mission-maker':{mode:'mission',theme:'maker',icon:'↟',kicker:{en:'MISSION MAKER',bn:'মিশন নির্মাতা'},intro:{en:'Choose the tools in the order that moves the project forward.',bn:'প্রকল্পকে এগিয়ে নিতে সঠিক ক্রমে সরঞ্জাম বেছে নাও।'},show:{en:'',bn:''},ask:{en:'Choose the next tool',bn:'পরের সরঞ্জামটি বেছে নাও'},rounds:[{sequence:['map','tape'],choices:['paint','map','tape','seed']},{sequence:['seed','water'],choices:['water','seed','paint','map']},{sequence:['paint','frame'],choices:['frame','paint','tape','seed']}]},
 'goal-street':{mode:'goal',theme:'pitch',icon:'⚽',kicker:{en:'GOAL STREET',bn:'গোল স্ট্রিট'},intro:{en:'Scan the street pitch and pass through the open lane.',bn:'পাড়ার মাঠ দেখে খোলা লেনে পাস দাও।'},show:{en:'',bn:''},ask:{en:'Where is the open lane?',bn:'খোলা লেনটি কোথায়?'},rounds:[{sequence:['left'],choices:[]},{sequence:['right'],choices:[]},{sequence:['left'],choices:[]},{sequence:['right'],choices:[]}]},
 'sky-scout':{mode:'scout',theme:'sky',icon:'☁',kicker:{en:'SKY SCOUT',bn:'আকাশ স্কাউট'},intro:{en:'Watch the moving sky and spot the scout signal.',bn:'চলমান আকাশ দেখো এবং স্কাউট সংকেতটি খুঁজে নাও।'},show:{en:'',bn:''},ask:{en:'',bn:''},rounds:[{sequence:['kite'],choices:['kite','bird','cloud','plane']},{sequence:['plane'],choices:['bird','plane','cloud','kite']},{sequence:['bird'],choices:['cloud','kite','bird','plane']},{sequence:['cloud'],choices:['plane','cloud','kite','bird']}]},
 'pet-village':{mode:'pet',theme:'pet',icon:'🐾',kicker:{en:'PET VILLAGE',bn:'পোষ্য পল্লি'},intro:{en:'Notice what each pet needs, then choose a kind next step.',bn:'প্রতিটি পোষ্যের কী দরকার লক্ষ্য করো, তারপর সহানুভূতিশীল পরের পদক্ষেপ বেছে নাও।'},show:{en:'',bn:''},ask:{en:'What could help next?',bn:'পরের কোন কাজটি সাহায্য করতে পারে?'},rounds:[{pet:'🐶',story:{en:'Milo is hiding after a loud celebration.',bn:'জোরে উদযাপনের পর মিলো লুকিয়ে আছে।'},sequence:['quiet_space'],choices:['quiet_space','loud_game','ignore']},{pet:'🐱',story:{en:'Tuli dropped her toy while the others are playing.',bn:'অন্যরা খেলছে, আর তুলি তার খেলনাটি ফেলে দিয়েছে।'},sequence:['offer_help'],choices:['offer_help','take_toy','walk_away']},{pet:'🐰',story:{en:'Bun is sitting alone beside a new game.',bn:'বান নতুন একটি খেলার পাশে একা বসে আছে।'},sequence:['invite_join'],choices:['invite_join','exclude','rush']}]},
 'rhythm-river':{mode:'rhythm',theme:'river',icon:'≈',kicker:{en:'RHYTHM RIVER',bn:'ছন্দ নদী'},intro:{en:'Watch the river rhythm, then tap it back.',bn:'নদীর ছন্দ দেখো, তারপর একই ছন্দে ট্যাপ করো।'},show:{en:'Watch the current',bn:'স্রোতটা দেখো'},ask:{en:'Tap the rhythm back',bn:'ছন্দটি আবার ট্যাপ করো'},rounds:[{sequence:['●','●'],choices:[]},{sequence:['●','●','●'],choices:[]},{sequence:['●','●','●','●'],choices:[]}]}
};
const labels:Record<string,Record<Lang,string>>={mango:{en:'Mango',bn:'আম'},book:{en:'Book',bn:'বই'},drum:{en:'Drum',bn:'ঢোল'},kite:{en:'Kite',bn:'ঘুড়ি'},lamp:{en:'Lamp',bn:'বাতি'},map:{en:'Map',bn:'মানচিত্র'},tape:{en:'Tape',bn:'ফিতা'},seed:{en:'Seed',bn:'বীজ'},water:{en:'Water',bn:'পানি'},paint:{en:'Paint',bn:'রং'},frame:{en:'Frame',bn:'ফ্রেম'},bird:{en:'Bird',bn:'পাখি'},cloud:{en:'Cloud',bn:'মেঘ'},plane:{en:'Plane',bn:'বিমান'},quiet_space:{en:'Make a quiet space',bn:'শান্ত জায়গা তৈরি করি'},loud_game:{en:'Start a loud game',bn:'জোরে খেলা শুরু করি'},ignore:{en:'Walk away',bn:'চলে যাই'},offer_help:{en:'Offer to help',bn:'সাহায্যের প্রস্তাব দিই'},take_toy:{en:'Take the toy',bn:'খেলনাটি নিয়ে নিই'},walk_away:{en:'Walk away',bn:'চলে যাই'},invite_join:{en:'Invite Bun to join',bn:'বানকে যোগ দিতে বলি'},exclude:{en:'Keep Bun out',bn:'বানকে বাইরে রাখি'},rush:{en:'Rush the game',bn:'তাড়াহুড়া করি'}};
const route=useRoute(),router=useRouter(),slug=computed(()=>String(route.params.slug)),config=computed(()=>configs[slug.value]||configs['memory-market']),language=gameLanguage,t=computed(()=>gameText[language.value]),displayName=computed(()=>gameNames[slug.value]?.[language.value]||slug.value),stage=ref<'intro'|'play'|'result'>('intro'),round=ref(1),correct=ref(0),answered=ref(0),locked=ref(false),showing=ref(false),selected=ref<string[]>([]),repeats=ref<string[]>([]),startedAt=ref(0),run=ref<GameRun|null>(null); const rounds=computed(()=>config.value.rounds); const current=computed(()=>rounds.value[round.value-1]); const label=(item:string)=>labels[item]?.[language.value]||item;
const start=async()=>{stage.value='play';round.value=1;correct.value=0;answered.value=0;selected.value=[];repeats.value=[];startedAt.value=Date.now();const id=Number(route.query.profileId);try{run.value=Number.isInteger(id)&&id>0?await startGame(slug.value,id):null;}catch{run.value=null;}present();};
const present=()=>{showing.value=config.value.mode==='memory'||config.value.mode==='rhythm';if(showing.value)window.setTimeout(()=>showing.value=false,1100);}; const record=(isCorrect:boolean,choice:string)=>{answered.value++;if(isCorrect)correct.value++;run.value?.events.push({event_type:'response',payload:{correct:isCorrect,response_ms:Date.now()-startedAt.value,round:round.value,mode:config.value.mode,choice},occurred_at:new Date().toISOString()});locked.value=true;window.setTimeout(next,300);}; const next=()=>{if(round.value>=rounds.value.length){finish();return;}round.value++;selected.value=[];repeats.value=[];startedAt.value=Date.now();locked.value=false;present();};
const memoryPick=(item:string)=>{if(locked.value)return;selected.value.push(item);if(selected.value.length===current.value.sequence.length)record(selected.value.join('|')===current.value.sequence.join('|'),selected.value.join('|'));}; const signalPick=()=>record(!!current.value.target,'catch');const signalPass=()=>record(!current.value.target,'pass');const missionPick=(item:string)=>{if(locked.value)return;selected.value.push(item);if(selected.value.length===current.value.sequence.length)record(selected.value.join('|')===current.value.sequence.join('|'),selected.value.join('|'));};const scoutPick=(item:string)=>record(current.value.sequence[0]===item,item);const petPick=(item:string)=>record(current.value.sequence[0]===item,item);const goalPick=(lane:string)=>record(current.value.sequence[0]===lane,lane);const rhythmTap=()=>{if(locked.value)return;repeats.value.push('●');if(repeats.value.length===current.value.sequence.length)record(true,`tap-${repeats.value.length}`);}; const finish=async()=>{if(stage.value!=='play')return;stage.value='result';locked.value=false;const active=run.value;run.value=null;if(active)await completeGame(active,{correct_choices:correct.value,attempted_rounds:answered.value,game_slug:slug.value});};const leave=()=>router.push({name:'GameLibrary',query:{profile:route.query.profile||'child'}});
</script>

<style scoped>.challenge{color:#fffaf0;min-height:100%;padding:18px}.market{background:linear-gradient(145deg,#a73851,#ed8d55)}.garden{background:linear-gradient(145deg,#125e55,#85b65d)}.maker{background:linear-gradient(145deg,#294e91,#8b70c9)}.river{background:linear-gradient(145deg,#174a70,#4ca9ad)}.pitch{background:linear-gradient(145deg,#146258,#4aa86b)}header{align-items:center;display:flex;justify-content:space-between;margin:auto;max-width:600px}header button,.link,.finish{background:transparent;border:0;color:inherit;cursor:pointer;font:inherit}header span{font:700 .72rem Georgia,serif;letter-spacing:.12em}.panel{background:#fffaf0;border-radius:28px;box-shadow:0 20px 55px #071d2d70;color:#182c3d;margin:34px auto;max-width:600px;padding:28px;text-align:center}.intro>p:first-child,.result>p{color:#a14636;font:700 .74rem Georgia,serif;letter-spacing:.12em}.intro h1,.result h1{font:400 clamp(3rem,12vw,5rem)/.9 Georgia,serif;letter-spacing:-.07em;margin:10px 0}.hero-icon{background:#f5c961;border-radius:50%;font:5rem Georgia,serif;height:145px;line-height:145px;margin:24px auto;width:145px}.intro p:not(:first-child),.result span{line-height:1.55}.primary{background:#182c3d;border:0;border-radius:100px;color:#fff;cursor:pointer;font:700 1rem Georgia,serif;margin-top:17px;padding:14px 19px}.status{display:flex;justify-content:space-between}.instruction{color:#566c66;margin:25px 0 12px}.sequence,.rhythm{background:#edf0e7;border-radius:20px;font:2.2rem Georgia,serif;letter-spacing:.08em;margin:10px 0 20px;min-height:88px;padding:24px}.tiles{display:grid;gap:10px;grid-template-columns:repeat(2,1fr)}.tiles button,.two-actions button{background:#f5d39f;border:0;border-radius:16px;color:#182c3d;cursor:pointer;font:1.05rem Georgia,serif;min-height:74px}.signal-orb{background:#4d675a;border:0;border-radius:50%;color:#dce3d8;cursor:pointer;font:5rem Georgia,serif;height:180px;margin:8px;width:180px}.signal-orb.target{background:#f5c961;color:#fff8cc;box-shadow:0 0 28px #f5c961}.two-actions{display:grid;gap:10px;grid-template-columns:1fr 1fr}.two-actions button:first-child{background:#f4d780}.build-path{background:#e9f0e7;border-radius:18px;display:flex;gap:8px;justify-content:center;margin:12px 0;padding:18px}.build-path span,.build-path i{background:#fff;border-radius:10px;font-style:normal;padding:8px}.pitch{border:8px solid #e6efd0;border-radius:20px;height:190px;margin:12px 0;position:relative}.pitch .goal{color:#fff;font-size:5rem;position:absolute;right:12%;top:18%}.pitch .defender{color:#194a45;font-size:3rem;position:absolute;top:42%}.pitch .defender.left{left:27%}.pitch .defender.right{right:27%}.pitch .defender.open{opacity:.25}.pitch .ball{bottom:17%;font-size:2.5rem;left:46%;position:absolute}.tap{background:#258c95;border:8px solid #b7e6dc;border-radius:50%;color:#fff;cursor:pointer;font-size:2rem;height:140px;width:140px}.hint{color:#607d79}.finish{color:#52675d;margin-top:18px;text-decoration:underline}.link{color:#385e50;display:block;margin:16px auto 0;text-decoration:underline}</style>
